const hb = [...v.querySelectorAll('h2')].find(x => /^Bonuses/.test(x.textContent.trim()));
if(hb && !v.querySelector('.bd509')){ const L = []; let n = hb.nextElementSibling; while(n && n.classList.contains('li')){ L.push(n); n = n.nextElementSibling; }
  if(L.length){ const box = document.createElement('div'); box.className = 'bd509'; hb.after(box);
    L.forEach(li => { const amt = li.querySelector('b.num'), plus = amt && amt.classList.contains('plus'); li.insertAdjacentHTML('afterbegin', `<span class="sg ${plus ? 'p' : 'm'}">${plus ? '+' : '−'}</span>`);
      const sm = li.querySelector('.grow .small.mute'); if(sm && sm.firstChild && sm.firstChild.nodeType === 3) sm.firstChild.textContent = sm.firstChild.textContent.replace(/^\d{4}-\d{2}-\d{2}/, m => day(m)); box.appendChild(li); }); } } }

    /* bonuses & deductions · 513: a summary, a month chart and one row per kind (tap for every entry as a small table) */
    const hb = [...v.querySelectorAll('h2')].find(x => /^Bonuses/.test(x.textContent.trim()));
    if(hb && !v.querySelector('.bd509')){ const L = []; let n = hb.nextElementSibling; while(n && n.classList.contains('li')){ L.push(n); n = n.nextElementSibling; }
      const A = (D.adj || []).map(a => ({ a, v: +(a.plus || 0) - +(a.minus || 0), k: String(a.subject || a.type || 'Other').trim(), m: String(a.date || '').slice(0, 7) }));
      if(L.length && A.length){ const box = document.createElement('div'); box.className = 'bd509 b513'; hb.after(box); L.forEach(li => li.remove());
        const bon = A.filter(x => x.v > 0), ded = A.filter(x => x.v < 0), sum = X => X.reduce((s, x) => s + Math.abs(x.v), 0), net = sum(bon) - sum(ded);
        const months = [...new Set(A.map(x => x.m).filter(Boolean))].sort().slice(-3), mx = Math.max(1, ...months.map(m => Math.max(sum(bon.filter(x => x.m === m)), sum(ded.filter(x => x.m === m)))));
        const mLab = m => { const p = m.split('-'); return new Date(+p[0], +p[1] - 1, 1).toLocaleDateString('en-GB', { month: 'short' }); };
        const G = {}; A.forEach(x => { const g = (x.v >= 0 ? '+' : '−') + x.k; (G[g] = G[g] || []).push(x); });
        const keys = Object.keys(G).sort((p, q) => (p[0] === q[0] ? sum(G[q]) - sum(G[p]) : p[0] === '+' ? -1 : 1)), gmx = Math.max(1, ...keys.map(g => sum(G[g])));
        box.innerHTML = `<div class="t513"><div class="p"><span>Bonuses</span><b>+${esc(peso(sum(bon)))}</b><em>${bon.length} time${bon.length === 1 ? '' : 's'}</em></div><div class="m"><span>Deductions</span><b>−${esc(peso(sum(ded)))}</b><em>${ded.length ? ded.length + ' time' + (ded.length === 1 ? '' : 's') : 'none ✓'}</em></div><div class="n"><span>Net effect</span><b>${net < 0 ? '−' : '+'}${esc(peso(Math.abs(net)))}</b><em>last 90 days</em></div></div>`
          + (months.length > 1 ? `<div class="c513">${months.map(m => { const b = sum(bon.filter(x => x.m === m)), d = sum(ded.filter(x => x.m === m)); return `<div class="col"><div class="bars"><i class="p" style="height:${b ? Math.max(4, b / mx * 100) : 0}%" title="Bonuses ${esc(peso(b))}">${b ? '<s>+' + esc(peso(b)) + '</s>' : ''}</i><i class="m" style="height:${d ? Math.max(4, d / mx * 100) : 0}%" title="Deductions ${esc(peso(d))}">${d ? '<s>−' + esc(peso(d)) + '</s>' : ''}</i></div><span>${esc(mLab(m))}</span></div>`; }).join('')}<div class="lg"><span><i style="background:#2FA36B"></i>bonuses</span><span><i style="background:#E07A62"></i>deductions</span></div></div>` : '')
          + keys.map(g => { const X = G[g].slice().sort((p, q) => String(q.a.date).localeCompare(String(p.a.date))), plus = g[0] === '+', s = sum(X);
            return `<details class="g513"><summary><span class="sg ${plus ? 'p' : 'm'}">${plus ? '+' : '−'}</span><span class="nm"><b>${esc(g.slice(1))}</b><small>${X.length} time${X.length === 1 ? '' : 's'}</small><span class="br"><i class="${plus ? 'p' : 'm'}" style="width:${Math.max(4, s / gmx * 100)}%"></i></span></span><b class="am ${plus ? 'p' : 'm'}">${plus ? '+' : '−'}${esc(peso(s))}</b></summary>
<table><tr><th>Date</th><th>Student</th><th>By</th><th style="text-align:right">Amount</th></tr>${X.map(x => `<tr title="${esc([x.a.cond, x.a.detail].filter(Boolean).join(' · '))}"><td>${esc(day(x.a.date))}</td><td>${esc(x.a.student || '—')}${x.a.cond ? `<small>${esc(x.a.cond)}</small>` : ''}${x.a.detail && x.a.by ? `<small>${esc(x.a.detail)}</small>` : ''}</td><td>${esc(x.a.by || '—')}</td><td class="num" style="text-align:right;color:${plus ? '#1E7A55' : '#C0533F'};font-weight:700">${plus ? '+' : '−'}${esc(peso(Math.abs(x.v)))}</td></tr>`).join('')}</table></details>`; }).join(''); }
      else if(L.length){ const box = document.createElement('div'); box.className = 'bd509'; hb.after(box);
        L.forEach(li => { const amt = li.querySelector('b.num'), plus = amt && amt.classList.contains('plus'); li.insertAdjacentHTML('afterbegin', `<span class="sg ${plus ? 'p' : 'm'}">${plus ? '+' : '−'}</span>`);
          const sm = li.querySelector('.grow .small.mute'); if(sm && sm.firstChild && sm.firstChild.nodeType === 3) sm.firstChild.textContent = sm.firstChild.textContent.replace(/^\d{4}-\d{2}-\d{2}/, m => day(m)); box.appendChild(li); }); } } }

